// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testFuzz_property(address from, address caddress, address[] memory _tos, uint256 v) public {
        vm.assume(_tos.length > 0);
        // To avoid actual token transfer reverts, we assume the call will succeed
        // by also assuming caddress is a valid ERC20 token that will not revert on transferFrom
        // For simplicity, we only test with a non-zero address that we expect to behave
        vm.assume(caddress != address(0));
        // We will try the call and catch any revert
        try c.transfer(from, caddress, _tos, v) returns (bool result) {
            assertTrue(result, "transfer should return true when it succeeds");
        } catch {
            // revert is allowed, we do not assert in that case
        }
    }
}
